def solve_nonogram(n, m, row_segments, col_segments):
    # Initialize the field with empty cells
    field = [['.' for _ in range(m)] for _ in range(n)]

    # Helper function to check if a given field satisfies the segments
    def satisfies_segments(field, segments):
        for row in field:
            count = 0
            for i in range(m):
                if row[i] == '*':
                    count += 1
                else:
                    if count > 0 and count != segments[count - 1]:
                        return False
                    count = 0
            if count > 0 and count != segments[count - 1]:
                return False
        return True

    # Helper function to print the field
    def print_field(field):
        for row in field:
            print(''.join(row))

    # Try to fill the field
    def fill_field(field, row_segments, col_segments, row, col):
        if row == n:
            if satisfies_segments(field, col_segments):
                return True
            return False
        if col == m:
            return fill_field(field, row_segments, col_segments, row + 1, 0)

        # Try to fill the current cell
        field[row][col] = '*'
        if fill_field(field, row_segments, col_segments, row, col + 1):
            return True
        # Try to leave the current cell empty
        field[row][col] = '.'
        if fill_field(field, row_segments, col_segments, row, col + 1):
            return True
        return False

    # Start filling the field from the first cell
    fill_field(field, row_segments, col_segments, 0, 0)

    # Print the final field
    print_field(field)

